mapper.select:
SELECT ADMIN_ID AS adminId, PASSWORD AS password, ADMIN_NAME AS
adminName, ROLE AS role
FROM admin WHERE ADMIN_ID = #{adminId}

SELECT O.ORDER_ID AS ORDER_ID, O.USER_ID AS USER_ID, DATE_FORMAT(O.CREATED_AT, '%Y-%m-%d %H:%i') AS CREATED_AT, O.TOTAL_PRICE AS TOTAL_PRICE, O.ORDER_STATUS AS ORDER_STATUS, (SELECT GROUP_CONCAT(P.PRODUCT_NAME SEPARATOR ', ') FROM ORDER_ITEM OI JOIN PRODUCT P ON OI.PRODUCT_ID = P.PRODUCT_ID WHERE OI.ORDER_ID = O.ORDER_ID) AS PRODUCT_NAME, (SELECT PI.IMG_URL FROM ORDER_ITEM OI JOIN product_img PI ON OI.PRODUCT_ID = PI.PRODUCT_ID WHERE OI.ORDER_ID = O.ORDER_ID ORDER BY PI.IS_MAIN DESC LIMIT 1) AS IMG_URL FROM ORDERS O
AND (O.ORDER_ID LIKE CONCAT('%', #{keyword}, '%') OR O.USER_ID LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY O.CREATED_AT DESC LIMIT #{offset}, #{pageSize}

SELECT p.PRODUCT_ID, p.PRODUCT_NAME, p.PRODUCT_TYPE, p.PRICE, p.DEPOSIT,
p.DESCRIPTION, p.IS_AVAILABLE, p.VIEW_COUNT, (SELECT IMG_URL FROM
product_img pi WHERE pi.PRODUCT_ID = p.PRODUCT_ID ORDER BY pi.IS_MAIN
DESC, pi.SORT_ORDER ASC LIMIT 1) AS IMG_URL, DATE_FORMAT(p.CREATED_AT,
'%Y-%m-%d') AS CREATED_AT FROM product p 

		AND p.PRODUCT_NAME LIKE CONCAT('%', #{keyword}, '%')


		AND p.PRODUCT_TYPE = #{productType}


		AND p.IS_AVAILABLE = #{isAvailable}


ORDER BY p.CREATED_AT DESC LIMIT #{offset}, #{pageSize}

mapper.update:
UPDATE product
SET PRODUCT_NAME = #{productName}, PRODUCT_TYPE = #{productType}, PRICE
= #{price},
DEPOSIT = #{deposit}, DESCRIPTION = #{description}
WHERE PRODUCT_ID = #{productId}

mapper.select:
SELECT I.INQUIRY_ID, I.USER_ID, I.TITLE, I.CONTENT, I.INQUIRY_STATUS AS STATUS, R.CONTENT AS ANSWER, DATE_FORMAT(I.CREATED_AT, '%Y-%m-%d %H:%i') AS CREATED_AT, (SELECT GROUP_CONCAT(IMG_URL) FROM inquiry_img WHERE INQUIRY_ID = I.INQUIRY_ID) AS IMG_URLS FROM inquiry I LEFT OUTER JOIN inquiry_reply R ON I.INQUIRY_ID = R.INQUIRY_ID
AND I.INQUIRY_STATUS = #{status}
ORDER BY I.INQUIRY_ID DESC

mapper.insert:
INSERT INTO inquiry_reply (INQUIRY_ID, CONTENT, CREATED_AT)
VALUES (#{inquiryId}, #{answer}, NOW())
ON DUPLICATE KEY UPDATE CONTENT = #{answer}

mapper.update:
UPDATE coupon
SET IS_ACTIVE = #{isActive}
WHERE COUPON_ID = #{couponId}
